export default async function HomePage() {
  const headersList = await headers()
  const userAgent = headersList.get('user-agent') || ''

  const posts: Post[] = await fetch(
    'https://jsonplaceholder.typicode.com/posts?_limit=5'
  ).then((res) => res.json())

  const timestamp = new Date().toISOString()

  return (
    <div>
      <h1>Welcome to My Blog</h1>
      <p>Server-side rendered at: {timestamp}</p>
      <p>Your user agent: {userAgent}</p>

      <h2>Recent Posts</h2>
      <ul>
        {posts.map((post) => (
          <li key={post.id}>
            <a href={`/blog/${post.id}`}>{post.title}</a>
          </li>
        ))}
      </ul>

      <NavigateButton href="/blog">View All Posts</NavigateButton>
    </div>
  )
}

import type { Metadata } from 'next'
import { notFound } from 'next/navigation'
import { BackButton } from '@/components/NavigateButton'
import type { Comment, Post } from '@/types'

export const revalidate = 300

interface BlogPostPageProps {
  params: Promise<{ id: string }>
}

export async function generateStaticParams(): Promise<{ id: string }[]> {
  const posts: Post[] = await fetch(
    'https://jsonplaceholder.typicode.com/posts'
  ).then((res) => res.json())

  return posts.slice(0, 10).map((post) => ({
    id: post.id.toString(),
  }))
}

export async function generateMetadata({
  params,
}: BlogPostPageProps): Promise<Metadata> {
  const { id } = await params

  try {
    const post: Post = await fetch(
      `https://jsonplaceholder.typicode.com/posts/${id}`,
      { next: { revalidate: 300 } }
    ).then((res) => res.json())

    if (!post?.id) {
      return { title: 'Post Not Found - My Blog' }
    }

    const description = post.body.substring(0, 160)

    return {
      title: `${post.title} - My Blog`,
      description,
      openGraph: {
        title: post.title,
        description,
      },
    }
  } catch {
    return { title: 'Post Not Found - My Blog' }
  }
}

export default async function BlogPostPage({ params }: BlogPostPageProps) {
  const { id } = await params

  try {
    const [post, comments]: [Post, Comment[]] = await Promise.all([
      fetch(`https://jsonplaceholder.typicode.com/posts/${id}`, {
        next: { revalidate: 300 },
      }).then((res) => res.json()),
      fetch(`https://jsonplaceholder.typicode.com/posts/${id}/comments`, {
        next: { revalidate: 300 },
      }).then((res) => res.json()),
    ])

    if (!post?.id) {
      notFound()
    }

    return (
      <article>
        <BackButton>← Back</BackButton>

        <h1>{post.title}</h1>
        <p>{post.body}</p>

        <h2>Comments ({comments.length})</h2>
        <div className="comments">
          {comments.map((comment) => (
            <div key={comment.id} className="comment">
              <h3>{comment.name}</h3>
              <p>{comment.body}</p>
              <small>By: {comment.email}</small>
            </div>
          ))}
        </div>
      </article>
    )
  } catch {
    notFound()
  }
}

