import { useEffect } from 'react'

export default function Error({
  error,
  reset,
}: {
  error: Error & { digest?: string }
  reset: () => void
}) {
  useEffect(() => {
    console.error(error)
  }, [error])

  return (
    <div className="error-page">
      <h1>An error occurred on client</h1>
      <p>Sorry, something went wrong.</p>
      <button onClick={() => reset()}>Try again</button>
    </div>
  )
}

import { NextResponse } from 'next/server'
import type { ApiPost } from '@/types'

export async function GET(): Promise<NextResponse<ApiPost[]>> {
  const posts: ApiPost[] = [
    { id: 1, title: 'First Post', content: 'This is the first post' },
    { id: 2, title: 'Second Post', content: 'This is the second post' },
  ]

  return NextResponse.json(posts)
}

export async function POST(request: Request): Promise<NextResponse> {
  const body = (await request.json()) as {
    title?: string
    content?: string
  }

  const { title, content } = body

  if (!title || !content) {
    return NextResponse.json(
      { error: 'Title and content are required' },
      { status: 400 }
    )
  }

  const newPost: ApiPost = {
    id: Date.now(),
    title,
    content,
    createdAt: new Date().toISOString(),
  }

  return NextResponse.json(newPost, { status: 201 })
}

import { NextResponse } from 'next/server'
import type { ApiPost } from '@/types'

interface RouteContext {
  params: Promise<{ id: string }>
}

export async function GET(
  _request: Request,
  context: RouteContext
): Promise<NextResponse<ApiPost>> {
  const { id } = await context.params

  const post: ApiPost = {
    id: parseInt(id, 10),
    title: `Post ${id}`,
    content: `This is the content for post ${id}`,
    createdAt: new Date().toISOString(),
  }

  return NextResponse.json(post)
}

export async function PUT(
  request: Request,
  context: RouteContext
): Promise<NextResponse<ApiPost>> {
  const { id } = await context.params
  const body = (await request.json()) as {
    title?: string
    content?: string
  }

  const { title, content } = body

  const updatedPost: ApiPost = {
    id: parseInt(id, 10),
    title: title || `Post ${id}`,
    content: content || `Updated content for post ${id}`,
    updatedAt: new Date().toISOString(),
  }

  return NextResponse.json(updatedPost)
}

export async function DELETE(
  _request: Request,
  context: RouteContext
): Promise<NextResponse<{ message: string }>> {
  const { id } = await context.params

  return NextResponse.json({
    message: `Post ${id} deleted successfully`,
  })
}

